"""bwkit/applier — schema-agnostic, idempotent, resumable action-plan applier (stdlib-only).
Reuses cas.commit + cas.acquire_lock. Never parses business YAML; the caller builds the
JSON plan. See design spec §12.3, §6.5, §8.3. Maps to §5.7 step 2 (lock) + step 6/7 (CAS)
+ §6.5/§8.3 ordered-step recovery."""
from __future__ import annotations

from pathlib import Path

from . import cas


class PlanError(Exception):
    """A plan is malformed."""


def apply_plan(root, plan: dict) -> dict:
    root = Path(root)
    action_id = plan.get("action_id") or "ACT-?"
    owner = plan.get("owner") or f"plan:{action_id}"
    steps = plan.get("steps")
    if not isinstance(steps, list):
        raise PlanError("plan missing 'steps' list")

    cas.acquire_lock(root, owner)  # LockError propagates -> caller coordinates
    results, action_status = [], "applied"
    try:
        for step in steps:
            res = _apply_step(root, step)
            results.append(res)
            if res["status"] == "failed":
                action_status = "failed"
                break
    finally:
        cas.release_lock(root, owner)

    return {"action_id": action_id, "results": results, "action_status": action_status}


def _apply_step(root: Path, step: dict) -> dict:
    step_id = step.get("step_id") or "?"
    op = step.get("op")
    rel = step.get("path")
    new_text = step.get("new_text")
    if op not in ("cas_commit", "write_new") or not rel or new_text is None:
        raise PlanError(f"step {step_id} malformed (need op/path/new_text)")
    path = root / rel

    if op == "write_new":
        if path.exists():
            if path.read_text(encoding="utf-8", errors="replace") == new_text:
                return {"step_id": step_id, "status": "skipped", "detail": "already present"}
            return {"step_id": step_id, "status": "failed",
                    "detail": "target exists with different content"}
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(new_text, encoding="utf-8")
        return {"step_id": step_id, "status": "applied", "detail": "wrote new file"}

    expected = step.get("expected_revision")
    if not isinstance(expected, int):
        raise PlanError(f"step {step_id} cas_commit needs integer expected_revision")
    try:
        current = cas.read_revision(path)
    except (FileNotFoundError, KeyError) as e:
        return {"step_id": step_id, "status": "failed", "detail": f"cannot read revision: {e}"}

    if current == expected:
        try:
            r = cas.commit(path, new_text, expected)
        except (cas.CasConflict, cas.BadRevisionBump) as e:
            return {"step_id": step_id, "status": "failed", "detail": f"CAS error: {e}"}
        return {"step_id": step_id, "status": "applied", "detail": f"revision->{r['revision']}"}
    if current == expected + 1:
        if path.read_text(encoding="utf-8", errors="replace") == new_text:
            return {"step_id": step_id, "status": "skipped", "detail": "already applied"}
        return {"step_id": step_id, "status": "failed",
                "detail": f"revision {current} present with different content"}
    return {"step_id": step_id, "status": "failed",
            "detail": f"revision conflict: expected {expected}, current {current}"}

"""bwkit/cas — single-writer lock + text-level revision CAS (stdlib-only).

Schema-agnostic and YAML-agnostic. See design spec §12.5. This module never
imports yaml and never imports from the legacy bw package.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import time
from pathlib import Path

LOCKNAME = ".bw-lock"
BACKUP_PREFIX = ".backup-"


class LockError(Exception):
    """Lock contention or owner mismatch."""


class CasConflict(Exception):
    """Current revision != expected_revision (no write performed)."""


class BadRevisionBump(Exception):
    """new_text top-level revision != expected_revision + 1."""


def content_hash(body: str) -> str:
    return hashlib.sha256(body.encode()).hexdigest()


def lock_path(root) -> Path:
    return Path(root) / "_bewater" / LOCKNAME


def acquire_lock(root, owner, ttl_seconds: int = 3600) -> dict:
    root = Path(root)
    (root / "_bewater").mkdir(parents=True, exist_ok=True)
    path = lock_path(root)
    info = {"owner": owner, "pid": os.getpid(), "acquired_at": time.time()}
    try:
        fd = os.open(str(path), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    except FileExistsError:
        holder = _read_lock(path)
        if holder is not None and not _is_stale(holder, ttl_seconds):
            raise LockError(f"locked by {holder.get('owner')}")
        tmp = path.with_name(f"{LOCKNAME}.tmp-{os.getpid()}")
        tmp.write_text(json.dumps(info))
        os.replace(tmp, path)  # atomic preempt of stale lock
        return info
    try:
        os.write(fd, json.dumps(info).encode())
    finally:
        os.close(fd)
    return info


def release_lock(root, owner) -> None:
    path = lock_path(Path(root))
    holder = _read_lock(path)
    if holder is None:
        return  # unlocked: no-op
    if holder.get("owner") != owner:
        raise LockError(f"lock held by {holder.get('owner')}, not {owner}")
    path.unlink()


def lock_status(root):
    return _read_lock(lock_path(Path(root)))


def _read_lock(path) -> dict | None:
    try:
        return json.loads(path.read_text())
    except (FileNotFoundError, ValueError):
        return None


def _is_stale(holder: dict, ttl_seconds: int) -> bool:
    pid = holder.get("pid")
    if not isinstance(pid, int):
        return True
    try:
        os.kill(pid, 0)
        running = True
    except ProcessLookupError:
        running = False
    except PermissionError:
        running = True
    if running:
        return (time.time() - holder.get("acquired_at", 0.0)) > ttl_seconds
    return True


_REVISION_RE = re.compile(r"(?m)^revision:\s*(\d+)\s*$")


def read_revision(path) -> int:
    text = Path(path).read_text()  # FileNotFoundError if absent
    m = _REVISION_RE.search(text)
    if not m:
        raise KeyError(f"no top-level 'revision:' field in {path}")
    return int(m.group(1))


def commit(path, new_text: str, expected_revision: int, *, keep_backups: int = 5) -> dict:
    path = Path(path)
    current = read_revision(path)  # FileNotFoundError propagates if missing
    if current != expected_revision:
        raise CasConflict(f"current revision {current} != expected {expected_revision}")
    m = _REVISION_RE.search(new_text)
    got = int(m.group(1)) if m else None
    if got != expected_revision + 1:
        raise BadRevisionBump(
            f"new_text revision must be {expected_revision + 1} (got {got})")
    _rotate_backup(path, keep_backups)
    tmp = path.with_name(f".tmp-{path.name}-{os.getpid()}")
    tmp.write_text(new_text)
    os.replace(tmp, path)  # atomic
    return {"revision": expected_revision + 1, "hash": content_hash(new_text)}


def _backup_sort_key(path: Path) -> tuple[int, int]:
    """Numeric sort key ``(revision, timestamp)`` for backup filenames.

    Backups are ``.backup-{stem}-{old_rev}-{time_ns}``; sorting the filename
    lexicographically mis-orders revisions past 9 (``'10' < '5'``). Sort by the
    trailing numeric revision and timestamp so the most recent backups survive
    rotation.
    """
    try:
        *_, rev, stamp = path.name.split("-")
        return (int(rev) if rev != "x" else -1, int(stamp))
    except (ValueError, TypeError):
        return (-1, 0)


def _rotate_backup(path: Path, keep_backups: int) -> None:
    parent = path.parent
    old_text = path.read_text()
    old_rev_m = _REVISION_RE.search(old_text)
    old_rev = old_rev_m.group(1) if old_rev_m else "x"
    backup = parent / f"{BACKUP_PREFIX}{path.stem}-{old_rev}-{time.time_ns()}"
    backup.write_text(old_text)
    backups = sorted(parent.glob(f"{BACKUP_PREFIX}{path.stem}-*"),
                     key=_backup_sort_key)
    for extra in backups[:-keep_backups]:
        extra.unlink()

"""Schema-agnostic artifact revision-chain integrity checks."""
from __future__ import annotations


def check_artifacts(records: list[dict]) -> dict:
    """Check artifact revision chains and return their unique heads.

    Each record supplies ``id``, ``revision``, and optionally a ``supersedes``
    mapping.  Only references to revisions of the same artifact participate in
    the chain; cross-artifact references are intentionally ignored.
    """
    errors: list[str] = []
    by_id: dict[str, dict[int, dict]] = {}

    for record in records:
        artifact_id = record["id"]
        revision = record["revision"]
        revisions = by_id.setdefault(artifact_id, {})
        if revision in revisions:
            errors.append(f"duplicate revision: {artifact_id} r{revision}")
            continue
        revisions[revision] = record

    heads: dict[str, int] = {}
    for artifact_id, revisions in by_id.items():
        predecessors: dict[int, int] = {}
        superseded: set[int] = set()
        for revision, record in revisions.items():
            target = record.get("supersedes")
            if not isinstance(target, dict) or target.get("id") != artifact_id:
                continue
            predecessor = target.get("revision")
            if predecessor is None:
                errors.append(
                    f"malformed supersedes: {artifact_id} r{revision} missing revision"
                )
                continue
            if predecessor not in revisions:
                errors.append(
                    f"missing predecessor: {artifact_id} r{revision} -> r{predecessor}"
                )
                continue
            predecessors[revision] = predecessor
            superseded.add(predecessor)

        _add_cycle_errors(artifact_id, predecessors, errors)
        artifact_heads = set(revisions) - superseded
        if len(artifact_heads) != 1:
            errors.append(
                f"invalid head count: {artifact_id} has {len(artifact_heads)} heads"
            )
        else:
            heads[artifact_id] = artifact_heads.pop()

    if errors:
        heads = {}
    return {"ok": not errors, "errors": errors, "heads": heads}


def _add_cycle_errors(
    artifact_id: str, predecessors: dict[int, int], errors: list[str]
) -> None:
    checked: set[int] = set()
    for start in predecessors:
        if start in checked:
            continue
        path: set[int] = set()
        current = start
        while current in predecessors and current not in checked:
            if current in path:
                errors.append(f"cycle: {artifact_id} r{current}")
                break
            path.add(current)
            current = predecessors[current]
        checked.update(path)
